css:
.resilient-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #d7e3ee;
    background: radial-gradient(120% 100% at 0% 0%, #102132 0%, #0a1622 55%, #060e17 100%);
    border-radius: 18px;
}

.resilient-container * {
    box-sizing: border-box;
}

.resilient-header {
    text-align: center;
    padding: 30px 22px 26px;
    background: linear-gradient(135deg, #0d2942 0%, #123a5c 50%, #0e7c8c 100%);
    color: #eaf6fb;
    border-radius: 16px;
    margin-bottom: 18px;
    box-shadow: 0 14px 36px rgba(0, 0, 0, 0.45);
    border: 1px solid rgba(56, 217, 220, 0.18);
}

.resilient-header h1 {
    margin: 12px 0 12px;
    font-size: 2.5rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
    text-shadow: 0 2px 14px rgba(56, 217, 220, 0.35);
}

.resilient-header-tag {
    display: inline-block;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 1.4px;
    font-weight: 700;
    color: #5ef0e6;
    background: rgba(94, 240, 230, 0.10);
    border: 1px solid rgba(94, 240, 230, 0.40);
    padding: 5px 14px;
    border-radius: 999px;
}

.resilient-subtitle {
    margin: 0 auto;
    max-width: 840px;
    font-size: 1rem;
    line-height: 1.6;
    color: #bcd6e6;
}

.resilient-portfolio {
    display: flex;
    align-items: stretch;
    gap: 12px;
    margin-bottom: 18px;
}

.resilient-seg {
    flex: 1;
    background: #0f2233;
    border-radius: 14px;
    padding: 14px 18px;
    box-shadow: inset 0 0 0 1px rgba(94, 240, 230, 0.08), 0 6px 16px rgba(0, 0, 0, 0.35);
    display: flex;
    flex-direction: column;
    gap: 5px;
}

.resilient-seg-ice { border-left: 5px solid #e0913a; }
.resilient-seg-sdv { border-left: 5px solid #38d9dc; }

.resilient-seg-name {
    font-weight: 800;
    font-size: 1.05rem;
    color: #eaf6fb;
}

.resilient-seg-ice .resilient-seg-name { color: #f0a955; }
.resilient-seg-sdv .resilient-seg-name { color: #5ef0e6; }

.resilient-seg-meta {
    font-size: 0.82rem;
    color: #8ba6ba;
    line-height: 1.45;
}

.resilient-seg-vs {
    align-self: center;
    font-size: 1.8rem;
    font-weight: 800;
    color: #5ef0e6;
}

.resilient-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #9fb6c8;
    margin-bottom: 16px;
    padding: 4px;
}

.resilient-period-counter #currentDay,
.resilient-period-counter #maxPeriods {
    font-weight: 800;
    color: #5ef0e6;
}

.resilient-round-name {
    background: rgba(94, 240, 230, 0.12);
    color: #5ef0e6;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
    border: 1px solid rgba(94, 240, 230, 0.25);
}

.resilient-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #f0a955;
    background: rgba(224, 145, 58, 0.12);
    border: 1px solid rgba(224, 145, 58, 0.32);
    padding: 4px 12px;
    border-radius: 999px;
}

.resilient-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.resilient-status-card {
    background: linear-gradient(160deg, #112839 0%, #0d2030 100%);
    border-radius: 14px;
    padding: 16px 16px 14px;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.38);
    border-top: 4px solid #38d9dc;
}

.resilient-card-resilience { border-top-color: #5ef0e6; }
.resilient-card-share { border-top-color: #6aa6ff; }
.resilient-card-slack { border-top-color: #c79bff; }
.resilient-card-margin { border-top-color: #5fd28a; }

.resilient-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #80a0b6;
}

.resilient-value {
    font-size: 2.55rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 5px 0 3px;
    color: #eaf6fb;
    font-variant-numeric: tabular-nums;
}

.resilient-card-resilience .resilient-value { color: #5ef0e6; }
.resilient-card-share .resilient-value { color: #6aa6ff; }
.resilient-card-slack .resilient-value { color: #c79bff; }
.resilient-card-margin .resilient-value { color: #5fd28a; }

.resilient-sublabel {
    font-size: 0.75rem;
    color: #7990a3;
    line-height: 1.4;
}

.resilient-card-resilience.resilient-danger { border-top-color: #ff6b6b; }
.resilient-card-resilience.resilient-danger .resilient-value { color: #ff6b6b; }
.resilient-card-resilience.resilient-good { border-top-color: #5fd28a; }
.resilient-card-resilience.resilient-good .resilient-value { color: #5fd28a; }

.resilient-card-share.resilient-share-danger .resilient-value { color: #ff6b6b; }
.resilient-card-slack.resilient-slack-danger .resilient-value { color: #ff6b6b; }
.resilient-card-margin.resilient-margin-danger .resilient-value { color: #ff6b6b; }

.resilient-clock-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #0f2233;
    border: 1px solid rgba(224, 145, 58, 0.28);
    color: #9fb6c8;
    padding: 11px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.9rem;
}

.resilient-clock-bar #pivotDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #f0a955;
    font-weight: 800;
}

.resilient-clock-bar.resilient-pivot-fast #pivotDisplay { color: #5fd28a; }
.resilient-clock-bar.resilient-pivot-slow #pivotDisplay { color: #ff6b6b; }

.resilient-briefing {
    display: flex;
    gap: 14px;
    background: #0f2233;
    border-left: 5px solid #38d9dc;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(0, 0, 0, 0.30);
}

.resilient-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.resilient-briefing-title {
    font-weight: 800;
    font-size: 1.1rem;
    color: #eaf6fb;
    margin-bottom: 6px;
}

.resilient-briefing-text {
    font-size: 0.95rem;
    line-height: 1.6;
    color: #b6cee0;
}

.resilient-briefing-text strong { color: #5ef0e6; }
.resilient-briefing-text em { color: #f0a955; font-style: italic; }

.resilient-controls {
    background: linear-gradient(160deg, #112839 0%, #0c1c2b 100%);
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.34);
    border: 1px solid rgba(94, 240, 230, 0.08);
}

.resilient-controls h3 {
    margin: 0 0 14px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #eaf6fb;
    border-bottom: 2px solid rgba(94, 240, 230, 0.18);
    padding-bottom: 8px;
}

.resilient-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #cfe0ee;
    margin: 16px 0 6px;
}

.resilient-container select,
.resilient-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #2a4a63;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #0a1825;
    color: #eaf6fb;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.resilient-container select:focus,
.resilient-container input[type="number"]:focus {
    outline: none;
    border-color: #38d9dc;
    box-shadow: 0 0 0 3px rgba(56, 217, 220, 0.22);
}

.resilient-container select option {
    background-color: #0a1825;
    color: #eaf6fb;
}

.resilient-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #38d9dc;
}

.resilient-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #9fb6c8;
    margin-top: 4px;
}

.resilient-range-readout span:nth-child(2) {
    color: #5ef0e6;
    font-weight: 800;
}

.resilient-budget-meter {
    margin-top: 12px;
    padding: 10px 14px;
    background: rgba(199, 155, 255, 0.10);
    border: 1px solid rgba(199, 155, 255, 0.32);
    border-radius: 10px;
    font-size: 0.92rem;
    font-weight: 700;
    color: #cfe0ee;
}

.resilient-budget-meter #remainingReadout {
    color: #c79bff;
    font-size: 1.15rem;
    font-weight: 800;
}

.resilient-budget-meter.resilient-overspent {
    background: rgba(255, 107, 107, 0.12);
    border-color: rgba(255, 107, 107, 0.45);
}

.resilient-budget-meter.resilient-overspent #remainingReadout { color: #ff6b6b; }

.resilient-hint {
    font-size: 0.8rem;
    color: #7990a3;
    margin-top: 8px;
    line-height: 1.45;
    font-style: italic;
}

.resilient-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.resilient-container .btn-primary {
    background: linear-gradient(135deg, #0e7c8c 0%, #38d9dc 100%);
    border: none;
    color: #06222a;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 20px rgba(56, 217, 220, 0.30);
}

.resilient-container .btn-primary:hover {
    filter: brightness(1.08);
}

.resilient-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #2a4a63;
    color: #9fb6c8;
    background: transparent;
}

.resilient-coach {
    background: linear-gradient(160deg, #0d2942 0%, #0a1c2e 100%);
    color: #cfe6e9;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 8px 22px rgba(0, 0, 0, 0.40);
    border: 1px solid rgba(94, 240, 230, 0.12);
}

.resilient-coach-header {
    font-size: 0.76rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #f0a955;
    margin-bottom: 8px;
}

.resilient-coach-body {
    font-size: 0.95rem;
    line-height: 1.6;
}

.resilient-coach-body strong { color: #5ef0e6; }
.resilient-coach-body em { color: #f0a955; font-style: italic; }

.resilient-history,
.resilient-chart {
    background: linear-gradient(160deg, #112839 0%, #0c1c2b 100%);
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.34);
    border: 1px solid rgba(94, 240, 230, 0.08);
}

.resilient-history h3,
.resilient-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #eaf6fb;
}

.resilient-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #b6cee0;
}

.resilient-container table#usfHistoryTable th {
    background: #0d2030;
    color: #5ef0e6;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.7rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #1f3c52;
}

.resilient-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #18303f;
    color: #b6cee0;
}

.resilient-container table#usfHistoryTable tr:nth-child(even) td {
    background: rgba(255, 255, 255, 0.02);
}

.resilient-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .resilient-container {
        padding: 14px;
    }
    .resilient-header h1 {
        font-size: 1.8rem;
    }
    .resilient-portfolio {
        flex-direction: column;
    }
    .resilient-seg-vs {
        transform: rotate(90deg);
    }
    .resilient-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .resilient-value {
        font-size: 2rem;
    }
    .resilient-clock {
        margin-left: 0;
    }
    .resilient-period-counter {
        font-size: 0.88rem;
    }
    .resilient-clock-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .resilient-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}

/* ============================================================================
   Completion debrief (v1.1.0) — namespaced .rbd-cm-*, append-only.
   Matches the sim's dark teal/navy palette. Rendered by
   ResilientByDesignAdapter.formatCompletionMessage().
   ============================================================================ */
.rbd-cm {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #d7e3ee;
    background: radial-gradient(120% 100% at 0% 0%, #102132 0%, #0a1622 55%, #060e17 100%);
    border: 1px solid rgba(94, 240, 230, 0.20);
    border-radius: 16px; padding: 22px 24px 24px; max-width: 720px; margin: 8px auto;
    box-shadow: 0 14px 36px rgba(3, 8, 14, 0.55);
}
.rbd-cm-head {
    display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap;
    border-bottom: 1px solid rgba(94, 240, 230, 0.18); padding-bottom: 14px; margin-bottom: 16px;
}
.rbd-cm-verdict { font-size: 1.5rem; font-weight: 800; letter-spacing: -0.3px; line-height: 1.15; }
.rbd-cm-good .rbd-cm-verdict { color: #5fd28a; }
.rbd-cm-mid  .rbd-cm-verdict { color: #f0a955; }
.rbd-cm-bad  .rbd-cm-verdict { color: #ff8a8a; }
.rbd-cm-score { display: flex; align-items: baseline; gap: 6px; white-space: nowrap; }
.rbd-cm-score-num { font-size: 2.1rem; font-weight: 800; color: #eaf6fb; }
.rbd-cm-score-max { font-size: 1rem; color: #9fb6c8; }
.rbd-cm-grade {
    margin-left: 10px; font-size: 0.82rem; font-weight: 700; color: #bff6f1;
    background: rgba(94, 240, 230, 0.14); border: 1px solid rgba(94, 240, 230, 0.30);
    padding: 3px 10px; border-radius: 999px;
}
.rbd-cm-kpis { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; margin-bottom: 16px; }
.rbd-cm-kpi {
    background: rgba(17, 40, 57, 0.6); border: 1px solid rgba(94, 240, 230, 0.16);
    border-radius: 12px; padding: 12px 10px; text-align: center;
}
.rbd-cm-kpi-val { font-size: 1.35rem; font-weight: 800; color: #eaf6fb; }
.rbd-cm-kpi-lbl { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 0.6px; color: #9fb6c8; margin-top: 4px; }
.rbd-cm-kpi.rbd-cm-ok { border-color: rgba(95, 210, 138, 0.5); box-shadow: inset 0 0 0 1px rgba(95, 210, 138, 0.14); }
.rbd-cm-kpi.rbd-cm-no { border-color: rgba(255, 107, 107, 0.42); }
.rbd-cm-gates-h, .rbd-cm-insights-h {
    font-size: 0.74rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700;
    color: #f0a955; margin: 6px 0 8px;
}
.rbd-cm-gates { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 16px; }
.rbd-cm-chip { font-size: 0.8rem; font-weight: 600; padding: 5px 11px; border-radius: 999px; border: 1px solid transparent; }
.rbd-cm-chip-ok { color: #052015; background: #5fd28a; }
.rbd-cm-chip-no { color: #ffd9d9; background: rgba(255, 107, 107, 0.16); border-color: rgba(255, 107, 107, 0.45); }
.rbd-cm-insights { margin: 0; padding-left: 18px; }
.rbd-cm-insights li { font-size: 0.92rem; line-height: 1.5; color: #c9d8e6; margin-bottom: 8px; }
@media (max-width: 560px) {
    .rbd-cm-kpis { grid-template-columns: repeat(2, 1fr); }
    .rbd-cm-head { flex-direction: column; align-items: flex-start; }
}

