(function() {
    'use strict';

    class ResilientByDesignAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Resilient by Design`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // ---- Numbers reference card (Aarav Mobility Systems Ltd.) ----
            this.BUDGET = 1200;          // ₹ cr hard ceiling for the cycle
            this.ACQ_COST = 380;         // ₹ cr — 40-engineer software firm
            this.GREENFIELD = 520;       // ₹ cr greenfield entry (USD $62M)
            this.JV = 240;               // ₹ cr JV entry (USD $29M)
            this.LICENSE = 70;           // ₹ cr licensing/export entry (USD $8M)
            this.START_RESILIENCE = 38;  // baseline Resilience Index
            this.START_MARGIN = 13.5;    // % EBITDA
            this.CONSTRAINT_FLOOR = 250; // ₹ cr — funding level that actually closes the software gap
            this.STARVE_CEILING = 100;   // ₹ cr — at/under this the named constraint is starved
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    resilience: this.START_RESILIENCE, // Resilience Index 0–100 (headline KPI)
                    share: 100,                        // % of contested EV/SDV share retained
                    slack: 0,                          // ₹ cr optionality reserve held
                    margin: this.START_MARGIN,         // group EBITDA margin %
                    pivotQ: 0,                         // quarters-to-pivot (0 = not yet triggered)
                    buildFunded: 0,                    // ₹ cr committed to the capability build
                    entryMode: ``,                     // chosen entry mode (code)
                    shockType: ``,                     // revealed shock (code)
                    // ---- Sticky run-defining penalty flags (set on error, gate top verdict) ----
                    coreLockFlag: false,               // over-defended the declining core
                    allInFlag: false,                  // committed everything, no reserve
                    greenfieldLockFlag: false,         // locked into sunk greenfield capital at the shock
                    starvedConstraintFlag: false,      // named the software gap then under-funded it
                    rescueNotRoutineFlag: false,       // handled the shock but built no standing routine
                    constraintNamed: false,            // correctly named the binding constraint in R1
                    resilienceHistory: [this.START_RESILIENCE],
                    shareHistory: [100],
                    slackHistory: [0],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults lean toward the COMMON ERRORS: defend the core,
                // misname the constraint, over-allocate ICE with almost no reserve,
                // greenfield + hold + ROI pitch. A blind click-through must NOT auto-win.
                state.decisions = {
                    constraint: `oem`,
                    dc: `sensing`,
                    posture: `milk`,
                    baseline: 38,
                    sustain: 700,
                    build: 120,
                    buildMode: `organic`,
                    entryRes: 80,
                    entry: `greenfield`,
                    pivot: `hold`,
                    useReserve: `debt`,
                    speed: 40,
                    reconfig: `ignore`,
                    routine: `none`,
                    pitch: `roi`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const c = document.getElementById(`constraintInput`);
                const dc = document.getElementById(`dcInput`);
                const po = document.getElementById(`postureInput`);
                const ba = document.getElementById(`baselineInput`);
                if (c) decisions.constraint = c.value;
                if (dc) decisions.dc = dc.value;
                if (po) decisions.posture = po.value;
                if (ba) decisions.baseline = parseInt(ba.value, 10);
                if (!Number.isFinite(decisions.baseline) || decisions.baseline < 20 || decisions.baseline > 60) {
                    warn(`warn_baseline_range`); return false;
                }
            } else if (round === 2) {
                const su = document.getElementById(`sustainInput`);
                const bu = document.getElementById(`buildInput`);
                const bm = document.getElementById(`buildModeInput`);
                const er = document.getElementById(`entryResInput`);
                if (su) decisions.sustain = parseInt(su.value, 10);
                if (bu) decisions.build = parseInt(bu.value, 10);
                if (bm) decisions.buildMode = bm.value;
                if (er) decisions.entryRes = parseInt(er.value, 10);
                if (!Number.isFinite(decisions.sustain) || !Number.isFinite(decisions.build) || !Number.isFinite(decisions.entryRes)) {
                    warn(`warn_alloc_number`); return false;
                }
                // The acquisition costs ₹380 cr — it must be funded from the build line.
                const buildNeed = decisions.buildMode === `acquire` ? this.ACQ_COST : 0;
                if (decisions.buildMode === `acquire` && decisions.build < buildNeed) {
                    warn(`warn_acq_underfunded`); return false;
                }
                const committed = decisions.sustain + decisions.build + decisions.entryRes;
                if (committed > this.BUDGET) {
                    warn(`warn_overspent`); return false;
                }
            } else if (round === 3) {
                const en = document.getElementById(`entryInput`);
                const pv = document.getElementById(`pivotInput`);
                const ur = document.getElementById(`useReserveInput`);
                const sp = document.getElementById(`speedInput`);
                if (en) decisions.entry = en.value;
                if (pv) decisions.pivot = pv.value;
                if (ur) decisions.useReserve = ur.value;
                if (sp) decisions.speed = parseInt(sp.value, 10);
                if (!Number.isFinite(decisions.speed) || decisions.speed < 0 || decisions.speed > 100) {
                    warn(`warn_speed_range`); return false;
                }
            } else if (round === 4) {
                const rc = document.getElementById(`reconfigInput`);
                const ro = document.getElementById(`routineInput`);
                const pi = document.getElementById(`pitchInput`);
                const cv = document.getElementById(`convictionInput`);
                if (rc) decisions.reconfig = rc.value;
                if (ro) decisions.routine = ro.value;
                if (pi) decisions.pitch = pi.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let resDelta = 0, shareDelta = 0, marginDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // ---- Diagnose. Naming the constraint correctly enables Round 2 to resource it. ----
                switch (d.constraint) {
                    case `software`:
                        ds.constraintNamed = true; resDelta += 5; coachKey = `coach_r1_software`; break;
                    case `oem`:
                        resDelta -= 2; coachKey = `coach_r1_oem`; break;
                    case `brand`:
                        resDelta -= 1; coachKey = `coach_r1_brand`; break;
                    case `capacity`:
                        resDelta -= 2; coachKey = `coach_r1_capacity`; break;
                }

                switch (d.dc) {
                    case `seizing`: resDelta += 4; if (d.constraint === `software`) coachKey = `coach_r1_sharp`; break;
                    case `transforming`: resDelta += 2; break;
                    case `sensing`: resDelta += 1; break;
                    case `none`: resDelta -= 3; coachKey = `coach_r1_dcnone`; break;
                }

                switch (d.posture) {
                    case `ambidextrous`: resDelta += 6; marginDelta += 0.2; break;
                    case `milk`: resDelta -= 4; marginDelta += 0.6; coachKey = `coach_r1_milk`; break;
                    case `abandon`: resDelta -= 3; marginDelta -= 1.2; coachKey = `coach_r1_abandon`; break;
                }

                // Baseline ambition: a credible, improvable baseline (not denial, not fantasy).
                if (d.baseline >= 30 && d.baseline <= 45) resDelta += 1;
                else if (d.baseline > 50) resDelta -= 2;

                summaryKey = (d.constraint === `software` && d.dc === `seizing` && d.posture === `ambidextrous`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // ---- Allocate the ₹1,200 cr budget. Reserve = optionality the board scores. ----
                const committed = d.sustain + d.build + d.entryRes;
                ds.slack = Math.max(0, this.BUDGET - committed);
                ds.buildFunded = d.build;

                // SUSTAIN: protects margin but over-defending the dying core is the headline trap.
                if (d.sustain >= 700) {
                    ds.coreLockFlag = true;          // STICKY: over-defended the declining core
                    marginDelta += 0.8;
                    resDelta -= 8;
                    coachKey = `coach_r2_milk`;
                } else if (d.sustain >= 450) {
                    marginDelta += 0.4; resDelta -= 1;
                } else if (d.sustain <= 150) {
                    marginDelta -= 1.5; resDelta += 1; // starving the cash engine hurts current margin
                } else {
                    marginDelta += 0.1; resDelta += 1;
                }

                // BUILD: must be funded to the level of the named constraint.
                if (d.buildMode === `acquire` && d.build >= this.ACQ_COST) {
                    resDelta += 12; marginDelta -= 0.8; coachKey = `coach_r2_acquire`;
                } else if (d.build >= this.CONSTRAINT_FLOOR) {
                    resDelta += 9; marginDelta -= 0.4;
                } else if (d.build <= this.STARVE_CEILING) {
                    // Named the gap in R1, then starved it here (Common Error 5).
                    if (ds.constraintNamed) { ds.starvedConstraintFlag = true; coachKey = `coach_r2_starve`; }
                    resDelta -= 5;
                } else {
                    resDelta += 3;
                }
                if (d.buildMode === `none`) { resDelta -= 4; if (coachKey === `coach_default`) coachKey = `coach_r2_buildnone`; }

                // RESERVE earmark feeds the entry move; but TOTAL slack is what matters for the pivot.
                if (ds.slack >= 250) {
                    resDelta += 9; if (coachKey === `coach_default`) coachKey = `coach_r2_reserve`;
                } else if (ds.slack >= 120) {
                    resDelta += 4;
                } else if (ds.slack <= 40) {
                    // Fully committed with (almost) no reserve — conviction without slack (Common Error 2).
                    ds.allInFlag = true;            // STICKY: no optionality
                    resDelta -= 9; coachKey = `coach_r2_allin`;
                }

                summaryKey = (!ds.coreLockFlag && !ds.allInFlag && !ds.starvedConstraintFlag && ds.slack >= 200 && d.build >= this.CONSTRAINT_FLOOR)
                    ? `sum_r2_good`
                    : (ds.coreLockFlag ? `sum_r2_milk` : (ds.allInFlag ? `sum_r2_allin` : (ds.starvedConstraintFlag ? `sum_r2_starve` : `sum_r2_weak`)));
            } else if (round === 3) {
                // ---- Entry mode + the demand shock. The shock direction is revealed here. ----
                ds.entryMode = d.entry;

                // Deterministic-but-"unpredictable" shock keyed to the player's own pre-shock bet,
                // so the wrong-shock lesson always bites the over-committed (decision-tree #2).
                if (ds.coreLockFlag) ds.shockType = `collapse`;      // defended ICE → ICE collapses faster
                else if (ds.allInFlag) ds.shockType = `revival`;     // all-in on EV → subsidy withdrawal revives ICE
                else ds.shockType = `insourcing`;                    // balanced → an OEM in-sources a module

                // Entry mode as an optionality decision (decision-tree #3).
                switch (d.entry) {
                    case `license`: resDelta += 3; break;            // capital-light, easy to flex
                    case `jv`: resDelta += 5; marginDelta -= 0.2; break; // fast, shared, reversible — best under a loaded shock
                    case `greenfield`:
                        // Locked into sunk capital when the shock lands mid-build.
                        ds.greenfieldLockFlag = true;                // STICKY: committed capital, can't flex
                        resDelta -= 6; marginDelta -= 0.6; coachKey = `coach_r3_greenfield`; break;
                }

                // Pivot response — speed is BOUGHT in advance by slack + capability.
                const slackFactor = Math.max(0, Math.min(1, ds.slack / 300));
                const capFactor = Math.max(0, Math.min(1, ds.buildFunded / this.CONSTRAINT_FLOOR));
                const adaptive = 0.6 * slackFactor + 0.4 * capFactor; // 0..1 readiness to pivot

                if (d.pivot === `reallocate`) {
                    resDelta += 6;
                    // How funded the pivot is matters.
                    if (d.useReserve === `reserve`) { resDelta += 4; coachKey = `coach_r3_pivot`; }
                    else if (d.useReserve === `debt`) { resDelta += 1; marginDelta -= 0.8; }
                    else if (d.useReserve === `cut`) { resDelta -= 4; coachKey = `coach_r3_cut`; } // sacrificing the future to react
                } else if (d.pivot === `hold`) {
                    resDelta -= 4; coachKey = `coach_r3_hold`;
                } else if (d.pivot === `double`) {
                    resDelta -= 2; coachKey = `coach_r3_double`;
                }

                // ---- Pivot-speed clock (quarters). Set BEFORE the shock by optionality. ----
                // No-optionality path → 4–5 quarters and 6–9 share points lost permanently.
                let q;
                if (ds.allInFlag || ds.coreLockFlag || ds.greenfieldLockFlag) {
                    q = 5 - Math.round(adaptive * 1.5);            // 4–5 quarters even if they try to react
                } else {
                    q = Math.max(1, Math.round(4 - adaptive * 3 - (d.pivot === `reallocate` ? 0.5 : 0)));
                }
                // A passive response can't pivot fast no matter the slack.
                if (d.pivot === `hold`) q = Math.max(q, 4);
                q = Math.max(1, Math.min(6, q));
                ds.pivotQ = q;

                // Share consequence of pivot speed.
                if (q >= 4) shareDelta -= (5 + (q - 4) * 2);       // 5–9 points, unrecoverable
                else if (q <= 2) shareDelta += 2;                  // fast pivot defends/recaptures a little
                else shareDelta -= 1;

                summaryKey = (d.entry === `greenfield`) ? `sum_r3_greenfield` :
                             (d.pivot === `hold` ? `sum_r3_hold` :
                             (d.pivot === `reallocate` && q <= 2 ? `sum_r3_good` : `sum_r3_weak`));
            } else if (round === 4) {
                // ---- Recover: reconfigure and institutionalise resilience. ----
                switch (d.reconfig) {
                    case `reconfigure`: resDelta += 6; shareDelta += 2; coachKey = `coach_r4_reconfig`; break;
                    case `patch`: resDelta += 1; break;
                    case `ignore`: resDelta -= 5; shareDelta -= 3; coachKey = `coach_r4_ignore`; break;
                }

                // The Salwan lesson: resilience is a ROUTINE, not a RESCUE.
                switch (d.routine) {
                    case `full`: resDelta += 10; coachKey = `coach_r4_routine`; break;
                    case `sensing`: resDelta += 3; break;
                    case `none`:
                        ds.rescueNotRoutineFlag = true;            // STICKY: handled the shock, built no routine
                        resDelta -= 6; coachKey = `coach_r4_norisk`; break;
                }

                switch (d.pitch) {
                    case `optionality`: resDelta += 5; if (d.routine === `full`) coachKey = `coach_r4_pitch`; break;
                    case `roi`: resDelta -= 3; coachKey = `coach_r4_roi`; break;
                    case `luck`: resDelta -= 4; coachKey = `coach_r4_luck`; break;
                }

                if (d.conviction >= 60) resDelta += 2;
                else if (d.conviction <= 25) resDelta -= 2;

                summaryKey = (d.reconfig === `reconfigure` && d.routine === `full` && d.pitch === `optionality`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // ---- Apply deltas (clamped). ----
            ds.resilience = Math.max(0, Math.min(100, Math.round(ds.resilience + resDelta)));
            ds.share = Math.max(0, Math.min(100, Math.round((ds.share + shareDelta) * 10) / 10));
            ds.margin = Math.max(-10, Math.min(30, Math.round((ds.margin + marginDelta) * 10) / 10));

            // ---- Sticky flags cap the Resilience Index: a run-defining error cannot reach the top band. ----
            if (ds.coreLockFlag) ds.resilience = Math.min(ds.resilience, 52);
            if (ds.allInFlag) ds.resilience = Math.min(ds.resilience, 50);
            if (ds.greenfieldLockFlag) ds.resilience = Math.min(ds.resilience, 60);
            if (ds.starvedConstraintFlag) ds.resilience = Math.min(ds.resilience, 55);
            if (ds.rescueNotRoutineFlag) ds.resilience = Math.min(ds.resilience, 62);

            ds.resilienceHistory.push(ds.resilience);
            ds.shareHistory.push(ds.share);
            ds.slackHistory.push(ds.slack);

            // ---- Persist the composite where the gradebook / AGS + history readers look ----
            // Framework contract (results_utils.php): express_resolveDomainScore reads
            // domainState.performance.overallScore first, then a top-level score; and
            // express_extractHistory reads history[].domainState.performance.overallScore.
            // addToHistory() deep-clones domainState into each snapshot, so writing it here
            // lands the per-period score in the gradebook by construction.
            const composite = this._composite(ds);
            ds.performance = { overallScore: composite, grade: this._gradeLetter(composite) };
            ds.score = composite;

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                resilience: ds.resilience,
                resDelta: Math.round(resDelta),
                share: ds.share,
                shareDelta: Math.round(shareDelta * 10) / 10,
                slack: ds.slack,
                margin: ds.margin,
                pivotQ: ds.pivotQ,
                shockType: ds.shockType,
                score: composite,
                overallScore: composite,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _resilienceBand(v) {
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            if (v >= 70) return t(`band_resilient`);
            if (v >= 50) return t(`band_adapting`);
            return t(`band_fragile`);
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`resilienceDisplay`, `domainState.resilience`, (v) => {
                const n = Math.round(Number(v));
                const card = document.querySelector(`.resilient-card-resilience`);
                if (card) {
                    card.classList.toggle(`resilient-danger`, n < 50);
                    card.classList.toggle(`resilient-good`, n >= 70);
                }
                return `${n}`;
            });

            uiManager.bind(`shareDisplay`, `domainState.share`, (v) => {
                const n = Number(v);
                const card = document.querySelector(`.resilient-card-share`);
                if (card) card.classList.toggle(`resilient-share-danger`, n < 94);
                return `${self._fmtNum(n)}%`;
            });

            uiManager.bind(`slackDisplay`, `domainState.slack`, (v) => {
                const n = Math.round(Number(v));
                const card = document.querySelector(`.resilient-card-slack`);
                if (card) card.classList.toggle(`resilient-slack-danger`, n <= 40);
                return `₹${n} cr`;
            });

            uiManager.bind(`marginDisplay`, `domainState.margin`, (v) => {
                const n = Number(v);
                const card = document.querySelector(`.resilient-card-margin`);
                if (card) card.classList.toggle(`resilient-margin-danger`, n < 8);
                return `${self._fmtNum(n)}%`;
            });

            uiManager.bind(`pivotDisplay`, `domainState.pivotQ`, (v) => {
                const q = Math.round(Number(v));
                const bar = document.querySelector(`.resilient-clock-bar`);
                if (q <= 0) {
                    if (bar) { bar.classList.remove(`resilient-pivot-fast`, `resilient-pivot-slow`); }
                    return window.mySimulation.t(`pivot_pending`);
                }
                if (bar) {
                    bar.classList.toggle(`resilient-pivot-fast`, q <= 2);
                    bar.classList.toggle(`resilient-pivot-slow`, q >= 4);
                }
                const unit = q === 1 ? window.mySimulation.t(`quarter_one`) : window.mySimulation.t(`quarter_many`);
                return `${q} ${unit}`;
            });

            // ---- Live slider readouts. ----
            this._wireReadout(`baselineInput`, `baselineReadout`);
            this._wireReadout(`speedInput`, `speedReadout`);

            // ---- Round-2 budget sliders: live remaining-reserve meter. ----
            const su = document.getElementById(`sustainInput`);
            const bu = document.getElementById(`buildInput`);
            const er = document.getElementById(`entryResInput`);
            const suR = document.getElementById(`sustainReadout`);
            const buR = document.getElementById(`buildReadout`);
            const erR = document.getElementById(`entryResReadout`);
            const remR = document.getElementById(`remainingReadout`);
            const meter = document.querySelector(`.resilient-budget-meter`);
            const recompute = function() {
                const s = su ? parseInt(su.value, 10) : 0;
                const b = bu ? parseInt(bu.value, 10) : 0;
                const e = er ? parseInt(er.value, 10) : 0;
                if (suR) suR.textContent = s;
                if (buR) buR.textContent = b;
                if (erR) erR.textContent = e;
                const remaining = self.BUDGET - (s + b + e);
                if (remR) remR.textContent = remaining;
                if (meter) meter.classList.toggle(`resilient-overspent`, remaining < 0);
            };
            [su, bu, er].forEach(function(el) { if (el) el.addEventListener(`input`, recompute); });
            recompute();
        }

        _wireReadout(inputId, readoutId) {
            const el = document.getElementById(inputId);
            const out = document.getElementById(readoutId);
            if (el && out) {
                out.textContent = el.value;
                el.addEventListener(`input`, function() { out.textContent = el.value; });
            }
        }

        _fmtNum(v) {
            // Locale-aware one-decimal: en "13.5", es "13,5". Drops a trailing ".0".
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            let s = (Math.round(v * 10) / 10).toFixed(1);
            if (s.endsWith(`.0`)) s = s.slice(0, -2);
            return lang === `es` ? s.replace(`.`, `,`) : s;
        }

        // Composite — the VERBATIM v1.0.0 board score, factored out so calculateResults()
        // can persist the same value every period that getPerformanceSummary() reports at
        // completion. Scoring is unchanged; this is a refactor, not a re-tune. (The run-defining
        // error flags cap the underlying resilience KPI in calculateResults, so their effect is
        // already baked into ds before this runs — the composite has no separate caps.)
        _composite(ds) {
            const resilience = Math.round(ds.resilience);
            const share = Math.round(ds.share * 10) / 10;
            const margin = Math.round(ds.margin * 10) / 10;
            const pivotQ = ds.pivotQ;
            const marginScore = Math.max(0, Math.min(100, (margin + 5) / 20 * 100));
            const pivotScore = pivotQ > 0 ? Math.max(0, 100 - (pivotQ - 1) * 22) : 60;
            return Math.round(resilience * 0.42 + share * 0.26 + pivotScore * 0.20 + marginScore * 0.12);
        }

        // Letter grade surfaced to the gradebook / AGS via domainState.performance.grade.
        _gradeLetter(c) {
            if (c >= 85) return `A`;
            if (c >= 70) return `B`;
            if (c >= 58) return `C`;
            if (c >= 45) return `D`;
            return `F`;
        }

        // Localize the internal (English) verdict tier id. The English id stays the stable key
        // the scoring logic keys on; the label is resolved for display only.
        _gradeLabel(id) {
            const t = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            const map = {
                'Resilient by Design':     `verdict_resilient_by_design`,
                'Adaptive but Exposed':    `verdict_adaptive_exposed`,
                'Core Trap':               `verdict_core_trap`,
                'Conviction Without Slack': `verdict_conviction_no_slack`,
                'Locked-In Capital':       `verdict_locked_capital`,
                'Starved the Constraint':  `verdict_starved_constraint`,
                'Rescue, Not Routine':     `verdict_rescue_not_routine`,
                'Mixed Outcome':           `verdict_mixed_outcome`,
                'Bent and Broke':          `verdict_bent_broke`
            };
            return map[id] ? t(map[id]) : id;
        }

        getChartConfig() {
            // Guarded translator: localize chart chrome, fall back to English literals if the
            // framework isn't ready when the config is first built.
            const t = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? window.mySimulation.t.bind(window.mySimulation) : null;
            const L = (k, fallback) => (t ? t(k) : fallback);
            return {
                resilienceChart: {
                    type: `line`,
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: L(`chart_ds_resilience`, `Resilience Index (0–100)`),
                                data: [],
                                borderColor: `#5ef0e6`,
                                backgroundColor: `rgba(94,240,230,0.12)`,
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25,
                                pointRadius: 5,
                                pointBackgroundColor: `#5ef0e6`,
                                yAxisID: `y`
                            },
                            {
                                label: L(`chart_ds_share`, `Market share retained (%)`),
                                data: [],
                                borderColor: `#6aa6ff`,
                                backgroundColor: `rgba(106,166,255,0.10)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#6aa6ff`,
                                yAxisID: `y`
                            },
                            {
                                label: L(`chart_ds_reserve`, `Optionality reserve (₹ cr ÷ 12)`),
                                data: [],
                                borderColor: `#c79bff`,
                                backgroundColor: `rgba(199,155,255,0.08)`,
                                borderWidth: 2,
                                borderDash: [5, 4],
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#c79bff`,
                                yAxisID: `y`
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            legend: { position: `bottom`, labels: { color: `#9fb6c8`, boxWidth: 14 } },
                            title: { display: false }
                        },
                        scales: {
                            y: {
                                beginAtZero: true, max: 100, position: `left`,
                                ticks: { color: `#80a0b6` }, grid: { color: `rgba(255,255,255,0.06)` },
                                title: { display: true, text: L(`chart_axis_index`, `0–100`), color: `#80a0b6` }
                            },
                            x: {
                                ticks: { color: `#80a0b6` }, grid: { color: `rgba(255,255,255,0.04)` },
                                title: { display: true, text: L(`chart_axis_round`, `Round`), color: `#80a0b6` }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.resilienceHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            // Reserve is in ₹ cr (0–600+); divide by 12 to share the 0–100 axis.
            const reserveScaled = ds.slackHistory.map((v) => Math.round(v / 12));
            return {
                resilienceChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.resilienceHistory.map((v) => Math.round(v)) },
                        { data: ds.shareHistory.map((v) => Math.round(v)) },
                        { data: reserveScaled }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const resilience = Math.round(ds.resilience);
            const share = Math.round(ds.share * 10) / 10;
            const slack = Math.round(ds.slack);
            const margin = Math.round(ds.margin * 10) / 10;
            const pivotQ = ds.pivotQ;

            const anyFlag = ds.coreLockFlag || ds.allInFlag || ds.greenfieldLockFlag || ds.starvedConstraintFlag || ds.rescueNotRoutineFlag;

            // Composite: resilience-weighted board score (the board scores resilience, not ROI
            // alone). Shares the _composite(ds) helper that calculateResults() persists every
            // period, so the completion composite == the last period's persisted score by
            // construction.
            const composite = this._composite(ds);

            const fastPivot = pivotQ > 0 && pivotQ <= 2;
            const shareHeld = share >= 95;
            const resilient = resilience >= 70;

            let performance = `Bent and Broke`;
            // Top verdict is GATED: no run-defining error flag may be set.
            if (resilient && shareHeld && fastPivot && !anyFlag && composite >= 78) performance = `Resilient by Design`;
            else if (resilience >= 60 && share >= 92 && !ds.coreLockFlag && !ds.allInFlag) performance = `Adaptive but Exposed`;
            else if (ds.coreLockFlag) performance = `Core Trap`;
            else if (ds.allInFlag) performance = `Conviction Without Slack`;
            else if (ds.greenfieldLockFlag) performance = `Locked-In Capital`;
            else if (ds.starvedConstraintFlag) performance = `Starved the Constraint`;
            else if (ds.rescueNotRoutineFlag && composite >= 55) performance = `Rescue, Not Routine`;
            else if (composite >= 55) performance = `Mixed Outcome`;

            const insights = [];
            if (performance === `Resilient by Design`) insights.push(window.mySimulation.t(`insight_resilient`));
            if (ds.coreLockFlag) insights.push(window.mySimulation.t(`insight_core`));
            if (ds.allInFlag) insights.push(window.mySimulation.t(`insight_allin`));
            if (ds.greenfieldLockFlag) insights.push(window.mySimulation.t(`insight_greenfield`));
            if (ds.starvedConstraintFlag) insights.push(window.mySimulation.t(`insight_starve`));
            if (ds.rescueNotRoutineFlag) insights.push(window.mySimulation.t(`insight_routine`));
            if (pivotQ >= 4) insights.push(window.mySimulation.t(`insight_slowpivot`));
            else if (fastPivot) insights.push(window.mySimulation.t(`insight_fastpivot`));
            if (!shareHeld && pivotQ >= 4) insights.push(window.mySimulation.t(`insight_sharelost`));
            if (insights.length === 0) insights.push(window.mySimulation.t(`insight_mixed`));

            return {
                resilience: resilience,
                share: share,
                slack: slack,
                margin: margin,
                pivotQ: pivotQ,
                fastPivot: fastPivot,
                shareHeld: shareHeld,
                resilient: resilient,
                anyFlag: anyFlag,
                composite: composite,
                grade: this._gradeLetter(composite),
                performance: this._gradeLabel(performance),
                performanceId: performance,
                shockType: ds.shockType,
                insights: insights
            };
        }

        // Rich, localized board debrief. Without this override the framework falls through to
        // the base "You completed N periods." stub and discards the composite, verdict, KPIs and
        // insights this sim already computes. Self-contained, namespaced (.rbd-cm-*) markup.
        formatCompletionMessage(summary) {
            const t = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            const s = summary || {};
            const esc = (v) => String(v == null ? `` : v).replace(/[&<>]/g, (c) => ({ '&': `&amp;`, '<': `&lt;`, '>': `&gt;` }[c]));

            const composite = Math.round(Number(s.composite) || 0);
            const grade = esc(s.grade || this._gradeLetter(composite));
            const verdict = esc(s.performance || ``);
            const id = s.performanceId || ``;
            const tone = (id === `Resilient by Design`) ? `good`
                : (id === `Adaptive but Exposed` || id === `Mixed Outcome` || id === `Rescue, Not Routine`) ? `mid` : `bad`;

            const pivotStr = (Number(s.pivotQ) > 0) ? (`Q` + Math.round(Number(s.pivotQ))) : `—`;
            const kpi = (label, value, ok) =>
                `<div class="rbd-cm-kpi ${ok ? `rbd-cm-ok` : `rbd-cm-no`}"><div class="rbd-cm-kpi-val">${value}</div><div class="rbd-cm-kpi-lbl">${label}</div></div>`;
            const chip = (ok, label) =>
                `<span class="rbd-cm-chip ${ok ? `rbd-cm-chip-ok` : `rbd-cm-chip-no`}">${ok ? `✓` : `✕`} ${label} · ${ok ? esc(t(`cm_met`)) : esc(t(`cm_missed`))}</span>`;

            const insights = Array.isArray(s.insights) ? s.insights : [];
            const insightsHtml = insights.length
                ? `<ul class="rbd-cm-insights">` + insights.map((x) => `<li>${esc(x)}</li>`).join(``) + `</ul>`
                : ``;

            return `
                <div class="rbd-cm rbd-cm-${tone}">
                    <div class="rbd-cm-head">
                        <div class="rbd-cm-verdict">${verdict}</div>
                        <div class="rbd-cm-score"><span class="rbd-cm-score-num">${composite}</span><span class="rbd-cm-score-max">/100</span><span class="rbd-cm-grade">${esc(t(`cm_grade`))} ${grade}</span></div>
                    </div>
                    <div class="rbd-cm-kpis">
                        ${kpi(esc(t(`cm_kpi_resilience`)), Math.round(Number(s.resilience) || 0), !!s.resilient)}
                        ${kpi(esc(t(`cm_kpi_share`)), this._fmtNum(Number(s.share) || 0) + `%`, !!s.shareHeld)}
                        ${kpi(esc(t(`cm_kpi_reserve`)), `₹` + Math.round(Number(s.slack) || 0) + ` cr`, (Number(s.slack) || 0) >= 120)}
                        ${kpi(esc(t(`cm_kpi_margin`)), this._fmtNum(Number(s.margin) || 0) + `%`, (Number(s.margin) || 0) >= 0)}
                    </div>
                    <div class="rbd-cm-gates-h">${esc(t(`cm_gates_heading`))}</div>
                    <div class="rbd-cm-gates">
                        ${chip(!!s.resilient, esc(t(`cm_gate_resilience`)))}
                        ${chip(!!s.shareHeld, esc(t(`cm_gate_share`)))}
                        ${chip(!!s.fastPivot, esc(t(`cm_gate_pivot`)) + ` (` + pivotStr + `)`)}
                        ${chip(!s.anyFlag, esc(t(`cm_gate_clean`)))}
                    </div>
                    <div class="rbd-cm-insights-h">${esc(t(`cm_insights_heading`))}</div>
                    ${insightsHtml}
                </div>
            `;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.coreLockFlag) return window.mySimulation.t(`hint_core`);
            if (ds.allInFlag) return window.mySimulation.t(`hint_allin`);
            if (ds.starvedConstraintFlag) return window.mySimulation.t(`hint_starve`);
            if (ds.greenfieldLockFlag && state.currentPeriod >= 3) return window.mySimulation.t(`hint_greenfield`);
            if (ds.pivotQ >= 4) return window.mySimulation.t(`hint_slowpivot`);
            if (state.currentPeriod >= 4 && ds.rescueNotRoutineFlag) return window.mySimulation.t(`hint_routine`);
            if (ds.resilience >= 65 && ds.slack >= 150) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            const self = this;
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.resilience`, label: `Resilience`, i18nKey: `col_resilience`, formatter: (v) => `${Math.round(v)}` },
                { key: `results.share`, label: `Share`, i18nKey: `col_share`, formatter: (v) => `${self._fmtNum(Number(v))}%` },
                { key: `results.slack`, label: `Reserve`, i18nKey: `col_slack`, formatter: (v) => `₹${Math.round(v)} cr` },
                { key: `results.margin`, label: `Margin`, i18nKey: `col_margin`, formatter: (v) => `${self._fmtNum(Number(v))}%` }
            ];
        }

        getPresets() { return null; }

        _updateBriefing(state) {
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;

            const titleEl = document.getElementById(`briefingTitle`);
            if (titleEl) titleEl.textContent = t(round.titleKey);
            const textEl = document.getElementById(`briefingText`);
            if (textEl) textEl.innerHTML = t(round.textKey);
            const nameEl = document.getElementById(`roundNameDisplay`);
            if (nameEl) nameEl.textContent = t(round.nameKey);
            const clockEl = document.getElementById(`clockDisplay`);
            if (clockEl) clockEl.textContent = t(round.clockKey);

            for (let i = 0; i < this.ROUNDS.length; i++) {
                const panel = document.getElementById(this.ROUNDS[i].panelId);
                if (panel) panel.style.display = (i === idx) ? `block` : `none`;
            }
        }

